#pragma once

/*
 * Extra bindings for esp-idf-sys. `usb_host_hid` is a managed component and
 * is therefore not part of the default ESP-IDF bindings.
 *
 * The guard macro is generated by esp-idf-sys when the remote component is
 * enabled, so bindgen still works if the component is not resolved.
 */
#if defined(ESP_IDF_COMP_ESPRESSIF__USB_HOST_HID_ENABLED)
#include "usb/usb_host.h"
#include "usb/hid_host.h"
#endif
